import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load sprite texture
  const textureMap = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with aspect ratio from atlas region (512x320 px)
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1.0);

  // Create material using TSL texture node
  const material = new MeshBasicNodeMaterial({
    map: texture(textureMap),
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply placement from specification
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Resource cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    textureMap.dispose();
    material.dispose();
  };

  return mesh;
}
